def report(gains):
    ints = []
    for i, g in enumerate(gains):
        cases = ",".join(
            '{"key":%s,"cost":1.000000,"gain":%s,"support":1.000000}'
            % (json.dumps(k), f"{v:.6f}")
            for k, v in sorted(g.items())
        )
        start = i
        end = i + 0.5
        threshold = "null" if i == 0 else f"{start:.6f}"
        ints.append(
            '{"start":%s,"end":%s,"threshold":%s,"pick":["a"],"n":1,'
            '"stability":1.000000,"worst":%s,"cases":[%s]}'
            % (f"{start:.6f}", f"{end:.6f}", threshold,
               json.dumps(min(g, key=lambda k: (g[k], k))), cases)
        )
    return '{"alpha":0.050000,"intervals":[%s]}\n' % ",".join(ints)

